!function(){"use strict";function BancoCtrl($scope,mS,toast,form){$scope.data={},$scope.bancos=[],$scope.maxSize=5,$scope.totalRecords=0,$scope.pageIndex=1,$scope.pageSize=100,$scope.recordsQuantity=[5,10,25,50],$scope.options={boundaryLinks:!1,limitSelect:!0,pageSelect:!0},$scope.query={order:"descripcion",limit:10,page:1},$scope.get=function(){mS.getData("get","/Banco/Get?pageIndex="+$scope.pageIndex+"&pageSize="+$scope.pageSize).then(response=>{"0"!=response.id?($scope.bancos=response.data,$scope.totalRecords=response.data[0].totalRecords):toast.toastr("warning",response.message,response.titleSms)})},$scope.get(),$scope.pagechanged=function(){$scope.get()},$scope.changePageSize=function(){$scope.pageIndex=1,$scope.get()},$scope.abrirModal=function(data,type){$scope.type=type,$scope.colorHeader=1==type?"bg-info":"bg-success",$scope.iconoModal=1==type?"fa fa-plus-circle":" fa fa-edit",$scope.tituloModal=1==type?"Agregar Banco":" Actualizar Banco",$scope.btnModal=1==type?" Guardar":" Actualizar",$scope.icono=1==type?"fa fa-save 5x":"fa fa-edit 5x",$scope.data=1==type?{}:data,$("#agregar").modal("show")},$scope.obtenerTresLetras=function(data){void 0!==data.descripcion&&($scope.data.codigo=form.obtenerTresLetras(data.descripcion))},$scope.saveUpdate=function(type){if(form.campo($scope.data.descripcion))toast.toastr("warning","Por favor, ingrese la descripción",$scope.tituloModal);else if(form.campo($scope.data.codigo))toast.toastr("warning","Por favor, ingrese el Código",$scope.tituloModal);else{var url=1==type?"/Banco/Post":"/Banco/Put";mS.getData("post",url,$scope.data).then((function(response){"0"!=response.id?1==response.id&&(toast.toastr("success",response.message,response.tilleSms),$scope.get(),$("#agregar").modal("hide")):toast.toastr("warning",response.message,response.tilleSms)}))}},$scope.delete=function(data){Swal.fire({icon:"warning",html:"<small>Esta seguro/a de eliminar esta Banco ahora?</small>",showConfirmButton:!0,confirmButtonText:"Si,eliminar!",showCancelButton:!0,cancelButtonText:"No, cancelar!",allowOutsideClick:!1}).then(response=>{response.value&&mS.getData("post","/Banco/Delete?idBanco="+data.idBanco).then(response=>{if("0"!=response.id)return"1"==response.id?(toast.toastr("success",response.message,response.titleSms),void $scope.get()):void 0;toast.toastr("warning",response.message,response.titleSms)},error=>console.log(error))})},$(".modal").on("hide.bs.modal",(function(e){$scope.data={},$scope.get()}))}angular.module("acontPlusApp").controller("bancoCtrl",BancoCtrl),BancoCtrl.$inject=["$scope","mainService","toastService","formulario"]}(window.angular);